def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    # Early game logic (n <= 7)
    if n <= 7:
        opp_early_d = False
        if n >= 1 and history[0][1] == 'D':
            opp_early_d = True
        if n >= 2 and history[1][1] == 'D':
            opp_early_d = True

        if opp_early_d:
            last_opp = history[-1][1]
            return 'D' if last_opp == 'D' else 'C'

        if n == 1:
            return 'C'
        if n == 2:
            return 'D'
        if n == 3:
            if history[2][1] == 'C':
                return 'C'
            else:
                return 'D'
        if n == 4:
            if history[3][1] == 'C':
                return 'D'
            else:
                return 'C'
        if n >= 5:
            if history[2][0] == 'D' and history[3][1] == 'C':
                if len(history) >= 2 and (history[-1][1] == 'D' or history[-2][1] == 'D'):
                    return 'C'
                return 'D'
            else:
                if history[-1][1] == 'D':
                    return 'D'
                return 'C'

    # n >= 8
    if (history[0][1] == 'C' and history[1][1] == 'C' and 
        history[2][0] == 'D' and history[3][1] == 'C'):
        recent = history[-3:]
        if any(b == 'D' for a, b in recent):
            return 'C'
        return 'D'

    last_opp = history[-1][1]
    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    if opp_c >= 95:
        return 'C'
    if opp_c <= 3 and n >= 20:
        return 'D'
    recent = history[-12:]
    opp_recent_c = sum(1 for a, b in recent if b == 'C')
    if opp_recent_c == 0:
        if rng.random() < 0.08:
            return 'C'
        return 'D'
    if opp_recent_c >= 11:
        return 'C'
    perceived_forgiveness = opp_c / n
    if perceived_forgiveness > 0.65:
        if last_opp == 'D' and history[-2][1] == 'C' and rng.random() < 0.7:
            return 'D'
        return 'C'
    if my_c / n > 0.75 and last_opp == 'D':
        return 'D'
    if n > 60 and opp_c > 35 and my_c < 30:
        return 'C'
    if last_opp == 'D':
        if rng.random() < 0.15 + 0.25 * (opp_recent_c / 12):
            return 'C'
        return 'D'
    if n % 10 == 9 and my_c > opp_c + 10:
        return 'D'
    return 'C'
